"""################################################################################################################## Multi-Agent and Monte Carlo Agents for Connect 4 AI Project                                                   ##                                                                                                               ## This module defines various agent classes used in the Connect 4 AI project. These agents implement different  ## strategies for playing the game, including random moves, Minimax with Alpha-Beta pruning, and Monte Carlo     ## simulations. The abstract base classes allow for extensibility, while the specific agents handle distinct AI  ## techniques for playing Connect 4.                                                                             ##################################################################################################################"""import numpy as npimport abcfrom collections import Counterfrom game_state import Connect4GameState, PLAYER_ONE, PLAYER_TWOclass Agent(object):    def __init__(self):        super(Agent, self).__init__()    @abc.abstractmethod    def get_action(self, game_state):        return    def stop_running(self):        passdef score_evaluation_function(current_game_state):    """    This default evaluation function just returns the score of the state.    The score is the same one displayed in the GUI.    This evaluation function is meant for use with adversarial search agents    (not reflex agents).    """    score = 0    score += current_game_state.get_all_four(2)    score -= current_game_state.get_all_four(1)    return scoreclass RandomAgent(Agent):    def __init__(self):        super().__init__()    def get_action(self, game_state):        return np.random.choice(game_state.get_legal_actions())class MultiAgentSearchAgent(Agent):    """    Abstract class for multi-agent search algorithms. Provides shared functionality for search.    agents like Minimax and AlphaBeta.    """    def __init__(self, evaluation_function='scoreEvaluationFunction', depth=2):        self.evaluation_function = score_evaluation_function        self.depth = depth    @abc.abstractmethod    def get_action(self, game_state):        returnclass AlphaBetaAgent(MultiAgentSearchAgent):    """    Implements the Minimax algorithm with Alpha-Beta pruning.    """    def get_action(self, game_state):        """        Returns the minimax action using self.depth and self.evaluationFunction        """        alpha = -np.inf        beta = np.inf        chosen_action = -1        biggest_val = -np.inf        for action in game_state.get_legal_actions():            successor = game_state.generate_successor(action, 1)            alpha = self.helper(successor, (2 * self.depth) - 1, 0, alpha,                                beta)            if alpha > biggest_val:                biggest_val = alpha                chosen_action = action            if beta <= alpha:                break        return chosen_action    def helper(self, game_state, depth, agent_index, alpha, beta):        """        Recursive helper function that alternates between maximizing for Player 1 and minimizing for Player 2,        implementing Alpha-Beta pruning.        """        if depth == 0 or game_state.done:            return self.evaluation_function(game_state)        if agent_index == 1:            for action in game_state.get_legal_actions():                suc = game_state.generate_successor(action, agent_index)                alpha = max(alpha, self.helper(suc, depth - 1, 0, alpha, beta))                if beta <= alpha:                    break            return alpha        else:            for action in game_state.get_legal_actions():                suc = game_state.generate_successor(action, agent_index)                beta = min(beta, self.helper(suc, depth - 1, 1, alpha, beta))                if beta <= alpha:                    break            return betaclass MonteCarloAgent:    """    Implements a Monte Carlo Tree Search (MCTS) algorithm by simulating multiple random games from each possible    move and selecting the one with the highest win rate.    """    def __init__(self, simulations=100):        self.simulations = simulations    def get_action(self, game_state):        """        Returns the move with the highest win rate based on the simulated games.        """        legal_moves = game_state.get_legal_actions()        best_move = None        best_win_rate = -1        for move in legal_moves:            win_rate = self.simulate_move(game_state, move, self.simulations)            if win_rate > best_win_rate:                best_win_rate = win_rate                best_move = move        return best_move    def simulate_move(self, game_state, move, simulations):        """        Simulates the specified number of games for a given move and returns the win rate.        """        wins = 0        for _ in range(simulations):            if self.simulate_game(game_state, move):                wins += 1        return wins / simulations    def simulate_game(self, game_state, move):        """        Plays out a random game starting from a given move, alternating turns until a win or draw is reached.        """        state = game_state.generate_successor(move, 1)        current_player = 0        while not state.done:            legal_moves = state.get_legal_actions()            if not legal_moves:                break            next_move = np.random.choice(legal_moves)            state = state.generate_successor(next_move, current_player)            current_player = 1 - current_player        return state.winning_move(PLAYER_TWO)